import { Container, Grid, Typography, Box, Button } from '@mui/material';
import { styled, useTheme } from '@mui/material/styles';
import { Link as RouterLink } from 'react-router-dom';
import ContentBlock from '../content/ContentBlock';

// Styled Components (exactly as in original)
const SectionWrapper = styled('div')(({ theme, bdColor, padd = '120px' }) => ({
    padding: `${padd} 10px`,
    width: '100%',
    height: '100%',
    background: bdColor,
    [theme.breakpoints.down('lg')]: {
        padding: '10px 0'
    }
}));

const ImageBox = styled(Box)({
    width: '100%',
    height: '100%',
    display: 'flex'
});

const SectionImage = styled('img')({
    width: '100%',
    height: 'auto',
    borderRadius: '12px'
});

const ContentBox = styled(Box)(({ theme }) => ({
    borderRadius: '16px',
    padding: '20px 40px',
    display: 'flex',
    color: theme.palette.dark.dark,
    flexDirection: 'column',
    justifyContent: 'center',
    [theme.breakpoints.down('md')]: {
        padding: '0px',
        minHeight: 'auto',
        textAlign: 'center'
    }
}));

const FeatureSectionGeneric = ({
    title,
    paragraph,
    image,
    imagePosition = 'right',
    buttons = [],
    showButtons = false,
    numberedList = [],
    bulletList = [],
    titleColor = '',
    titleHighlightColor = '',
    titleHighlightText = '',
    titleFontSize = 'h2',
    titleHighlightFontSize = '',
    titleFont = '3.5rem',
    bdColor = '#ddf3f0',
    buttonPara,
    padd,
    col = '8',
    col1 = '4',
    headingPra
}) => {
    const theme = useTheme();

    const renderTitle = () => {
        if (!titleHighlightText) {
            return (
                <Typography
                    variant={titleFontSize}
                    sx={{
                        fontSize: { xs: '2rem', md: titleFont }, // Smaller font on mobile
                        fontWeight: 'bold',
                        mb: 2,
                        color: titleColor || 'inherit',
                        textAlign: { xs: 'center', md: numberedList.length > 0 || bulletList.length > 0 ? 'left' : 'left' }
                    }}
                >
                    {title}
                </Typography>
            );
        }

        const parts = title.split(titleHighlightText);

        return (
            <Typography
                variant={titleFontSize}
                sx={{
                    fontWeight: 'bold',
                    fontSize: { xs: '2rem', md: titleFont }, // Smaller font on mobile
                    mb: 2,
                    color: titleColor || 'inherit',
                    textAlign: { xs: 'center', md: numberedList.length > 0 || bulletList.length > 0 ? 'left' : 'left' }
                }}
            >
                {parts[0]}
                <Box
                    component="span"
                    sx={{
                        color: titleHighlightColor || theme.palette.primary.main,
                        fontSize: titleHighlightFontSize || 'inherit'
                    }}
                >
                    {titleHighlightText}
                </Box>
                {parts[1]}
            </Typography>
        );
    };

    const renderContent = () => {
        if (numberedList.length > 0) {
            return (
                <Grid container spacing={4}>
                    {numberedList.map((item, index) => (
                        <Grid item xs={12} sm={12} key={index}>
                            <Box
                                sx={{
                                    display: 'flex',
                                    alignItems: 'flex-start',
                                    gap: 2,
                                    flexDirection: { xs: 'column', md: 'row' },
                                    textAlign: { xs: 'center', md: 'left' }
                                }}
                            >
                                <Typography
                                    sx={{
                                        fontSize: '1.5rem',
                                        fontWeight: 900,
                                        backgroundColor: theme.palette.primary.light,
                                        borderRadius: '50%',
                                        width: '2.5rem',
                                        height: '2.5rem',
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        color: theme.palette.primary.contrastText,
                                        flexShrink: 0,
                                        position: 'relative',
                                        mx: { xs: 'auto', md: 0 }, // Center on mobile
                                        '&::before, &::after': {
                                            content: '""',
                                            position: 'absolute',
                                            backgroundColor: theme.palette.primary.main
                                        }
                                    }}
                                >
                                    {index + 1}
                                </Typography>
                                <Box>
                                    <Typography
                                        variant="h6"
                                        sx={{
                                            fontWeight: 700,
                                            mb: 1,
                                            fontSize: { xs: '1.5rem', sm: '1em', md: '1.2rem' },
                                            textAlign: { xs: 'center', md: 'left' }
                                        }}
                                    >
                                        {item.heading}
                                    </Typography>
                                    <Typography
                                        variant="body1"
                                        sx={{
                                            fontWeight: 400,
                                            lineHeight: 1.7,
                                            fontSize: { xs: '1rem', sm: '1em', md: '1.2rem' },
                                            textAlign: { xs: 'center', md: 'left' }
                                        }}
                                    >
                                        {item.paragraph}
                                    </Typography>
                                </Box>
                            </Box>
                        </Grid>
                    ))}
                </Grid>
            );
        }

        if (bulletList.length > 0) {
            return (
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                    {headingPra && (
                        <Typography
                            variant="h4"
                            component="div"
                            sx={{
                                fontSize: { xs: '1.75rem', sm: '2rem', md: '2rem' },
                                fontWeight: 300,
                                lineHeight: 1.4,
                                textAlign: { xs: 'center', md: 'left' },
                                color: titleColor
                            }}
                        >
                            {headingPra}
                        </Typography>
                    )}
                    {bulletList.map((item, index) => (
                        <Box
                            key={index}
                            sx={{
                                display: 'flex',
                                alignItems: 'flex-start',
                                gap: 2,
                                flexDirection: { xs: 'column', md: 'row' },
                                textAlign: { xs: 'center', md: 'left' }
                            }}
                        >
                            <Box
                                sx={{
                                    width: '8px',
                                    height: '8px',
                                    borderRadius: '50%',
                                    backgroundColor: theme.palette.primary.main,
                                    mt: { xs: 0, md: '10px' },
                                    flexShrink: 0,
                                    mx: { xs: 'auto', md: 0 } // Center on mobile
                                }}
                            />
                            <Box>
                                <Typography
                                    variant="body1"
                                    sx={{
                                        lineHeight: 1.7,
                                        textAlign: { xs: 'center', md: 'left' }
                                    }}
                                >
                                    <Box
                                        component="span"
                                        sx={{
                                            fontWeight: 'bold',
                                            fontSize: '1.2rem',
                                            display: 'block',
                                            mb: { xs: 1, md: 0 }
                                        }}
                                    >
                                        {item.heading}
                                    </Box>
                                    <Box component="span">{item.paragraph}</Box>
                                </Typography>
                            </Box>
                        </Box>
                    ))}
                </Box>
            );
        }

        return (
            <Typography
                variant="body1"
                sx={{
                    fontSize: '1.1rem',
                    lineHeight: 1.7,
                    fontWeight: 400,
                    textAlign: { xs: 'center', md: 'left' }
                }}
            >
                {paragraph}
            </Typography>
        );
    };
    return (
        <SectionWrapper bdColor={bdColor} padd={padd}>
            <Container maxWidth="xl">
                <Grid container spacing={0} alignItems="center">
                    <Grid item xs={12} md={imagePosition === 'right' ? col : col} order={{ xs: 1, md: imagePosition === 'right' ? 1 : 2 }}>
                        <ContentBox>
                            {title && renderTitle()}
                            {renderContent()}

                            {buttons.length > 0 && (
                                <Box
                                    sx={{
                                        display: 'flex',
                                        justifyContent: { xs: 'center', md: 'flex-start' }, // Center on mobile
                                        gap: 1,
                                        overflowX: 'auto',
                                        whiteSpace: 'nowrap',
                                        '&::-webkit-scrollbar': {
                                            display: 'none'
                                        },
                                        mt: 3
                                    }}
                                >
                                    {buttons.map((button, index) => (
                                        <Button
                                            key={index}
                                            variant={button.variant}
                                            component={RouterLink}
                                            to={button.to}
                                            sx={{
                                                backgroundColor: button?.backgroundColor,
                                                color: button.color,
                                                whiteSpace: 'nowrap',
                                                minWidth: 'max-content',
                                                padding: button.padding || '6px 12px',
                                                flexShrink: 0,
                                                textTransform: button.textTransform || 'uppercase',
                                                ...button.sx
                                            }}
                                        >
                                            {button.text}
                                        </Button>
                                    ))}
                                </Box>
                            )}

                            {buttonPara && (
                                <Typography
                                    variant="body1"
                                    sx={{
                                        fontSize: '1rem',
                                        lineHeight: 1.7,
                                        fontWeight: 400,
                                        textAlign: { xs: 'center', md: 'left' } // Center on mobile
                                    }}
                                >
                                    {buttonPara}
                                </Typography>
                            )}
                        </ContentBox>
                    </Grid>

                    <Grid
                        item
                        xs={12}
                        md={imagePosition === 'right' ? col1 : col1}
                        order={{ xs: 2, md: imagePosition === 'right' ? 2 : 1 }}
                    >
                        <ImageBox>
                            <SectionImage src={image} alt="Section Image" />
                        </ImageBox>
                    </Grid>
                </Grid>
            </Container>
        </SectionWrapper>
    );
};

export default FeatureSectionGeneric;
