import { Box, Typography, Button, Container } from '@mui/material';
import { useTheme } from '@mui/styles';
import { Link as RouterLink } from 'react-router-dom';

const CenteredActionBox = ({
    title,
    button1,
    button2,
    bgcolor = '#f9fafc',
    paddingBox = { xs: '3rem 1rem', md: '5rem' },
    varientB = 'h1'
}) => {
    const theme = useTheme();

    return (
        <Box
            sx={{
                padding: paddingBox,
                backgroundColor: bgcolor,
                width: '100%',
                textAlign: 'center'
            }}
        >
            <Container maxWidth="md">
                <Typography
                    variant={varientB}
                    sx={{
                        fontWeight: 500,
                        mb: { xs: 3, md: 4 },
                        color: theme.palette.text.primary,
                        lineHeight: 1.3,
                        fontSize: { xs: '1.8rem', sm: '2.2rem', md: '3rem' } // Responsive font size
                    }}
                >
                    {title}
                </Typography>
                <Box
                    sx={{
                        display: 'flex',
                        justifyContent: 'center',
                        gap: { xs: 2, md: 3 },
                        flexWrap: 'wrap',
                        flexDirection: { xs: 'column', sm: 'row' } // Stack buttons vertically on mobile
                    }}
                >
                    {button1 && (
                        <Button
                            variant="contained"
                            sx={{
                                px: { xs: 3, md: 4 },
                                py: { xs: 1, md: 1.5 },
                                fontSize: { xs: '0.9rem', md: '1rem' },
                                bgcolor: button1.bgcolor,
                                color: theme.palette.secondary.dark,
                                borderRadius: '8px',
                                minWidth: { xs: '200px', sm: 'auto' },
                                '&:hover': {
                                    bgcolor: theme.palette.primary.dark,
                                    color: theme.palette.text.primary
                                }
                            }}
                            to={button1.link}
                            component={RouterLink}
                        >
                            {button1.text}
                        </Button>
                    )}
                    {button2 && (
                        <Button
                            variant="contained"
                            sx={{
                                px: { xs: 3, md: 4 },
                                py: { xs: 1, md: 1.5 },
                                fontSize: { xs: '0.9rem', md: '1rem' },
                                bgcolor: theme.palette.text.primary,
                                color: theme.palette.text.dark,
                                borderRadius: '8px',
                                minWidth: { xs: '200px', sm: 'auto' },
                                '&:hover': {
                                    bgcolor: theme.palette.primary.light,
                                    borderColor: theme.palette.primary.dark
                                }
                            }}
                            to={button2?.link}
                            component={RouterLink}
                        >
                            {button2?.text}
                        </Button>
                    )}
                </Box>
            </Container>
        </Box>
    );
};

export default CenteredActionBox;
